})
const dressed = dress(body, "zai", device, {})
const h = new Headers({ "content-type": "application/json" })
startHeaders(h, jwt)
const res = await fetch(`${ZCODE}/api/v1/zcode-plan/anthropic/v1/messages`, { method: "POST", headers: h, body: dressed })
const text = await res.text()
console.log(`model=${MODEL} status=${res.status} ${res.statusText}`)
let short = text
try {
  const v = JSON.parse(text)
  if (v?.content?.length) short = JSON.stringify({ type: v.type, text: v.content.map((c) => c.text ?? `[${c.type}]`).join(""), stop: v.stop_reason, usage: v.usage })
  else short = text.slice(0, 300)
} catch { short = text.slice(0, 300) }
